package co.sena.academic.adapter.out.persistence;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(schema="academic_management",name="learning_outcome") public class LearningOutcomeJpaEntity {
 @Id private UUID id; @Column(name="competency_id",nullable=false) private UUID competencyId; @Column(nullable=false,length=20) private String code; @Column(nullable=false) private String description; @Column(name="is_active",nullable=false) private boolean active; @Version @Column(name="row_version",nullable=false) private int rowVersion; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="created_by",nullable=false) private UUID createdBy; @Column(name="updated_at",nullable=false) private Instant updatedAt; @Column(name="updated_by",nullable=false) private UUID updatedBy; @Column(name="deleted_at") private Instant deletedAt; @Column(name="deleted_by") private UUID deletedBy;
 protected LearningOutcomeJpaEntity(){} public LearningOutcomeJpaEntity(UUID id,UUID competencyId,String code,String description,boolean active,int rowVersion,Instant createdAt,UUID createdBy,Instant updatedAt,UUID updatedBy,Instant deletedAt,UUID deletedBy){this.id=id;this.competencyId=competencyId;this.code=code;this.description=description;this.active=active;this.rowVersion=rowVersion;this.createdAt=createdAt;this.createdBy=createdBy;this.updatedAt=updatedAt;this.updatedBy=updatedBy;this.deletedAt=deletedAt;this.deletedBy=deletedBy;}
 public UUID getId(){return id;} public UUID getCompetencyId(){return competencyId;} public String getCode(){return code;} public String getDescription(){return description;} public boolean isActive(){return active;} public int getRowVersion(){return rowVersion;} public Instant getCreatedAt(){return createdAt;} public UUID getCreatedBy(){return createdBy;} public Instant getUpdatedAt(){return updatedAt;} public UUID getUpdatedBy(){return updatedBy;} public Instant getDeletedAt(){return deletedAt;} public UUID getDeletedBy(){return deletedBy;}
}
